using System;
using System.Data;
using System.Drawing;
using System.Text.RegularExpressions;
using System.Windows.Forms;
using Npgsql;
using Cyusa_Divince_Lab3.Controllers;
using Cyusa_Divince_Lab3.Models;

namespace Cyusa_Divince_Lab3
{
    public class AppForm : Form
    {
        Staff user; TabControl tabs; DataGridView farmers, deliveries, payments; ComboBox deliveryFarmer, period; TextBox farmerFilter; readonly FarmerController farmerController = new FarmerController(); readonly AuthenticationController authenticationController = new AuthenticationController();
        public AppForm() { Text = "Dairy Cooperative Management"; StartPosition = FormStartPosition.CenterScreen; MinimumSize = new Size(1000, 650); Load += Start; }
        void Start(object s, EventArgs e) { try { Database.Initialize(); if (Database.HasStaff()) Login(); else FirstAdmin(); } catch (Exception x) { MessageBox.Show("PostgreSQL connection failed. Edit the DairyDb connection string in App.config.\n\n" + x.Message); Close(); } }
        void FirstAdmin() { var p = Page("First administrator setup"); var u = TextBoxAt(p, "Username", 35, 100); var a = TextBoxAt(p, "Password", 35, 165); a.UseSystemPasswordChar = true; var b = TextBoxAt(p, "Confirm password", 35, 230); b.UseSystemPasswordChar = true; var save = ButtonAt(p, "Create administrator", 35, 300); save.Click += (s, e) => { if (string.IsNullOrWhiteSpace(u.Text) || a.Text.Length < 6 || a.Text != b.Text) { MessageBox.Show("Enter a username and matching password of at least 6 characters."); return; } try { Database.CreateStaff(u.Text, a.Text, "Administrator"); MessageBox.Show("Account created. Sign in now."); Login(); } catch (Exception x) { MessageBox.Show(Error(x)); } }; Set(p); }
        void Login() { var p = Page("Staff sign in"); var u = TextBoxAt(p, "Username", 35, 100); var a = TextBoxAt(p, "Password", 35, 165); a.UseSystemPasswordChar = true; var go = ButtonAt(p, "Sign in", 35, 230); go.Click += (s, e) => { if (string.IsNullOrWhiteSpace(u.Text) || string.IsNullOrWhiteSpace(a.Text)) { MessageBox.Show("Username and password are required."); return; } try { user = authenticationController.Login(u.Text, a.Text); if (user == null) { MessageBox.Show("Invalid username or password."); return; } Dashboard(); } catch (Exception x) { MessageBox.Show(Error(x)); } }; a.KeyDown += (s, e) => { if (e.KeyCode == Keys.Enter) go.PerformClick(); }; Set(p); }
        void Dashboard() { var root = new Panel { Dock = DockStyle.Fill }; var head = new Panel { Dock = DockStyle.Top, Height = 60, BackColor = Color.FromArgb(35, 92, 63) }; head.Controls.Add(new Label { Text = user.Username + " (" + user.Role + ")", ForeColor = Color.White, Font = new Font("Segoe UI", 12, FontStyle.Bold), Location = new Point(20, 18), AutoSize = true }); var home = ButtonAt(head, "Home", 700, 15); home.Anchor = AnchorStyles.Top | AnchorStyles.Right; home.Click += (s, e) => tabs.SelectedIndex = 0; var outb = ButtonAt(head, "Logout", 830, 15); outb.Width = 145; outb.Anchor = AnchorStyles.Top | AnchorStyles.Right; outb.Click += (s, e) => Logout(); tabs = new TabControl { Dock = DockStyle.Fill }; tabs.TabPages.Add(HomeTab()); if (user.Role != "Treasurer") tabs.TabPages.Add(FarmersTab()); if (user.Role != "Treasurer") tabs.TabPages.Add(DeliveriesTab()); if (user.Role == "Administrator") tabs.TabPages.Add(StaffTab()); tabs.TabPages.Add(PaymentsTab()); root.Controls.Add(tabs); root.Controls.Add(head); Set(root); }
        TabPage HomeTab() { var p = new TabPage("Home"); LabelAt(p, "Welcome, " + user.Username, 30, 30, 600, 35, true, 18); LabelAt(p, "Choose a section to continue:", 30, 85, 400, 25, false, 11); var x = 30; if (user.Role != "Treasurer") { var farmersButton = ButtonAt(p, "Farmers", x, 130); farmersButton.Click += (s, e) => SelectTab("Farmers"); x += 140; var deliveriesButton = ButtonAt(p, "Milk deliveries", x, 130); deliveriesButton.Width = 130; deliveriesButton.Click += (s, e) => SelectTab("Milk deliveries"); x += 150; } if (user.Role == "Administrator") { var staffButton = ButtonAt(p, "Staff accounts", x, 130); staffButton.Width = 130; staffButton.Click += (s, e) => SelectTab("Staff accounts"); x += 150; } var paymentsButton = ButtonAt(p, "Payments", x, 130); paymentsButton.Click += (s, e) => SelectTab("Payments"); var logout = ButtonAt(p, "Logout", 30, 190); logout.Click += (s, e) => Logout(); return p; }
        void SelectTab(string title) { foreach (TabPage page in tabs.TabPages) if (page.Text == title) { tabs.SelectedTab = page; return; } }
        void Logout() { if (MessageBox.Show("Do you want to log out?", "Confirm logout", MessageBoxButtons.YesNo, MessageBoxIcon.Question) == DialogResult.Yes) { user = null; Login(); } }
        TabPage FarmersTab() { var p = new TabPage("Farmers"); var n = TextBoxAt(p, "Name", 20, 55); var ph = TextBoxAt(p, "Phone", 210, 55); ph.MaxLength = 10; var a = TextBoxAt(p, "Address", 400, 55); var save = ButtonAt(p, "Save", 590, 55); save.Click += (s, e) => { if (!Required(n, ph, a)) return; try { farmerController.Save(new Farmer { Name = n.Text, Phone = ph.Text, Address = a.Text }); LoadFarmers(); LoadDeliveryFarmers(); ResetFields(n, ph, a); MessageBox.Show("Farmer saved."); } catch (Exception x) { MessageBox.Show(Error(x)); } }; farmerFilter = TextBoxAt(p, "Search name/member number", 20, 120); var find = ButtonAt(p, "Search", 210, 120); find.Click += (s, e) => LoadFarmers(); farmerFilter.KeyDown += (s, e) => { if (e.KeyCode == Keys.Enter) find.PerformClick(); }; farmers = Grid(p, 20, 170); farmers.DoubleClick += (s, e) => { if (farmers.CurrentRow != null) { n.Text = "" + farmers.CurrentRow.Cells[2].Value; ph.Text = "" + farmers.CurrentRow.Cells[3].Value; a.Text = "" + farmers.CurrentRow.Cells[4].Value; } }; LoadFarmers(); return p; }
        TabPage DeliveriesTab() { var p = new TabPage("Milk deliveries"); deliveryFarmer = new ComboBox { Location = new Point(20, 55), Width = 190, DropDownStyle = ComboBoxStyle.DropDownList }; p.Controls.Add(deliveryFarmer); LabelAt(p, "Farmer", 20, 35); var date = new DateTimePicker { Location = new Point(220, 55), Width = 120, Format = DateTimePickerFormat.Short }; p.Controls.Add(date); LabelAt(p, "Date", 220, 35); var session = Combo(p, "Session", 355, 55, new[] { "Morning", "Evening" }); var litres = TextBoxAt(p, "Litres", 490, 55); var status = Combo(p, "Status", 600, 55, new[] { "Accepted", "Rejected" }); var reason = TextBoxAt(p, "Rejection reason", 730, 55); var save = ButtonAt(p, "Save", 885, 55); save.Click += (s, e) => { decimal l; if (deliveryFarmer.SelectedValue == null || !decimal.TryParse(litres.Text, out l) || l <= 0 || (status.Text == "Rejected" && string.IsNullOrWhiteSpace(reason.Text))) { MessageBox.Show("Select a farmer, enter litres greater than zero, and give a rejection reason when required."); return; } try { Database.Execute("INSERT INTO deliveries(farmer_id,delivery_date,session,litres,status,rejection_reason,recorded_by) VALUES(@f,@d,@s,@l,@st,@r,@u)", Database.Parameter("f", deliveryFarmer.SelectedValue), Database.Parameter("d", date.Value.Date), Database.Parameter("s", session.Text), Database.Parameter("l", l), Database.Parameter("st", status.Text), Database.Parameter("r", status.Text == "Rejected" ? reason.Text.Trim() : null), Database.Parameter("u", user.Id)); LoadDeliveries(); ResetFields(litres, reason); date.Value = DateTime.Today; session.SelectedIndex = 0; status.SelectedIndex = 0; if (deliveryFarmer.Items.Count > 0) deliveryFarmer.SelectedIndex = 0; MessageBox.Show("Delivery saved."); } catch (Exception x) { MessageBox.Show(Error(x)); } }; deliveries = Grid(p, 20, 130); LoadDeliveryFarmers(); LoadDeliveries(); return p; }
        TabPage StaffTab() { var p = new TabPage("Staff accounts"); var u = TextBoxAt(p, "Username", 20, 60); var pass = TextBoxAt(p, "Password", 210, 60); pass.UseSystemPasswordChar = true; var role = Combo(p, "Role", 400, 60, new[] { "Administrator", "Clerk", "Treasurer" }); var add = ButtonAt(p, "Create account", 580, 60); add.Click += (s, e) => { if (string.IsNullOrWhiteSpace(u.Text) || pass.Text.Length < 6) { MessageBox.Show("Username is required and password must have at least 6 characters."); return; } try { Database.CreateStaff(u.Text, pass.Text, role.Text); ResetFields(u, pass); role.SelectedIndex = 0; MessageBox.Show("Staff account created."); } catch (Exception x) { MessageBox.Show(Error(x)); } }; return p; }
        TabPage PaymentsTab() { var p = new TabPage("Payments"); if (user.Role == "Administrator") { var name = TextBoxAt(p, "Period name", 20, 60); var price = TextBoxAt(p, "Price/litre", 210, 60); var start = DateAt(p, "Start", 380, 60); var end = DateAt(p, "End", 510, 60); var make = ButtonAt(p, "Create period", 650, 60); make.Click += (s, e) => { decimal x; if (string.IsNullOrWhiteSpace(name.Text) || !decimal.TryParse(price.Text, out x) || x < 0 || end.Value < start.Value) { MessageBox.Show("Enter a valid name, price, and date range."); return; } try { Database.Execute("INSERT INTO payment_periods(name,start_date,end_date,price_per_litre) VALUES(@n,@s,@e,@p)", Database.Parameter("n", name.Text.Trim()), Database.Parameter("s", start.Value.Date), Database.Parameter("e", end.Value.Date), Database.Parameter("p", x)); ResetFields(name, price); start.Value = DateTime.Today; end.Value = DateTime.Today; LoadPeriods(); MessageBox.Show("Payment period created."); } catch (Exception z) { MessageBox.Show(Error(z)); } }; } period = new ComboBox { Location = new Point(20, 145), Width = 330, DropDownStyle = ComboBoxStyle.DropDownList }; p.Controls.Add(period); period.SelectedIndexChanged += (s, e) => LoadPayments(); var refresh = ButtonAt(p, "Refresh", 370, 145); refresh.Click += (s, e) => { LoadPeriods(); LoadPayments(); }; payments = Grid(p, 20, 195); if (user.Role == "Treasurer") { var paid = ButtonAt(p, "Mark selected as paid", 20, 535); paid.Click += (s, e) => MarkPaid(); } LoadPeriods(); return p; }
        void MarkPaid() { if (payments.CurrentRow == null) { MessageBox.Show("Select a payment."); return; } using (var d = new Form { Text = "Payment note", Size = new Size(400, 150), StartPosition = FormStartPosition.CenterParent }) { var t = new TextBox { Location = new Point(15, 15), Width = 350 }; var b = new Button { Text = "Save", Location = new Point(15, 55), DialogResult = DialogResult.OK }; d.Controls.Add(t); d.Controls.Add(b); d.AcceptButton = b; if (d.ShowDialog(this) != DialogResult.OK || string.IsNullOrWhiteSpace(t.Text)) { MessageBox.Show("A payment note is required."); return; } try { Database.Execute("UPDATE payments SET status='Paid',payment_date=CURRENT_DATE,payment_note=@n,paid_by=@u WHERE id=@id", Database.Parameter("n", t.Text.Trim()), Database.Parameter("u", user.Id), Database.Parameter("id", payments.CurrentRow.Cells[0].Value)); LoadPayments(); } catch (Exception x) { MessageBox.Show(Error(x)); } } }
        void LoadFarmers() { if (farmers != null) farmers.DataSource = farmerController.Search(farmerFilter == null ? "" : farmerFilter.Text.Trim()); }
        void LoadDeliveryFarmers() { if (deliveryFarmer != null) { deliveryFarmer.DataSource = Database.Query("SELECT id,member_number||' - '||name display FROM farmers ORDER BY name"); deliveryFarmer.DisplayMember = "display"; deliveryFarmer.ValueMember = "id"; } }
        void LoadDeliveries() { if (deliveries != null) deliveries.DataSource = Database.Query("SELECT d.id,f.member_number,f.name,d.delivery_date,d.session,d.litres,d.status,COALESCE(d.rejection_reason,'') rejection_reason FROM deliveries d JOIN farmers f ON f.id=d.farmer_id ORDER BY d.delivery_date DESC"); }
        void LoadPeriods() { if (period != null) { period.DataSource = Database.Query("SELECT id,name||' ('||start_date||' - '||end_date||')' display FROM payment_periods ORDER BY start_date DESC"); period.DisplayMember = "display"; period.ValueMember = "id"; } }
        void LoadPayments() { if (payments == null || period.SelectedValue == null) return; Database.Execute("INSERT INTO payments(period_id,farmer_id,accepted_litres,amount) SELECT @p,f.id,COALESCE(SUM(CASE WHEN d.status='Accepted' THEN d.litres ELSE 0 END),0),COALESCE(SUM(CASE WHEN d.status='Accepted' THEN d.litres ELSE 0 END),0)*pp.price_per_litre FROM farmers f CROSS JOIN payment_periods pp LEFT JOIN deliveries d ON d.farmer_id=f.id AND d.delivery_date BETWEEN pp.start_date AND pp.end_date WHERE pp.id=@p GROUP BY f.id,pp.price_per_litre ON CONFLICT(period_id,farmer_id) DO UPDATE SET accepted_litres=EXCLUDED.accepted_litres,amount=EXCLUDED.amount WHERE payments.status='Unpaid'", Database.Parameter("p", period.SelectedValue)); payments.DataSource = Database.Query("SELECT p.id,f.member_number,f.name,p.accepted_litres,p.amount,p.status,p.payment_date,COALESCE(p.payment_note,'') payment_note FROM payments p JOIN farmers f ON f.id=p.farmer_id WHERE p.period_id=@p ORDER BY f.name", Database.Parameter("p", period.SelectedValue)); }
        void ResetFields(params Control[] fields) { foreach (var field in fields) { var text = field as TextBox; if (text != null) { text.Clear(); continue; } var combo = field as ComboBox; if (combo != null && combo.Items.Count > 0) { combo.SelectedIndex = 0; } } }
        bool Required(params TextBox[] a) { foreach (var x in a) if (string.IsNullOrWhiteSpace(x.Text)) { MessageBox.Show("All fields are required."); x.Focus(); return false; } return true; }
        Panel Page(string title) { var p = new Panel { Dock = DockStyle.Fill, BackColor = Color.White }; LabelAt(p, title, 35, 25, 700, 35, true, 18); return p; }
        void Set(Control c) { Controls.Clear(); Controls.Add(c); }
        TextBox TextBoxAt(Control p, string label, int x, int y) { LabelAt(p, label, x, y - 20); var t = new TextBox { Location = new Point(x, y), Width = 170 }; p.Controls.Add(t); return t; }
        ComboBox Combo(Control p, string label, int x, int y, string[] values) { LabelAt(p, label, x, y - 20); var c = new ComboBox { Location = new Point(x, y), Width = 115, DropDownStyle = ComboBoxStyle.DropDownList }; c.Items.AddRange(values); c.SelectedIndex = 0; p.Controls.Add(c); return c; }
        DateTimePicker DateAt(Control p, string label, int x, int y) { LabelAt(p, label, x, y - 20); var d = new DateTimePicker { Location = new Point(x, y), Width = 115, Format = DateTimePickerFormat.Short }; p.Controls.Add(d); return d; }
        Button ButtonAt(Control p, string text, int x, int y) { var b = new Button { Text = text, Location = new Point(x, y), Width = 120, Height = 30 }; p.Controls.Add(b); return b; }
        void LabelAt(Control p, string text, int x, int y, int w = 170, int h = 20, bool bold = false, int size = 9) { p.Controls.Add(new Label { Text = text, Location = new Point(x, y), Width = w, Height = h, AutoSize = true, Font = new Font("Segoe UI", size, bold ? FontStyle.Bold : FontStyle.Regular) }); }
        DataGridView Grid(Control p, int x, int y) { var g = new DataGridView { Location = new Point(x, y), Width = 940, Height = 330, Anchor = AnchorStyles.Top | AnchorStyles.Bottom | AnchorStyles.Left | AnchorStyles.Right, ReadOnly = true, AutoSizeColumnsMode = DataGridViewAutoSizeColumnsMode.Fill, SelectionMode = DataGridViewSelectionMode.FullRowSelect, MultiSelect = false }; p.Controls.Add(g); return g; }
        string Error(Exception x) { var p = x as PostgresException; if (p != null && p.SqlState == "23505") return "That record already exists."; if (p != null && p.SqlState == "23514") return "The supplied values failed a validation rule."; return x.Message; }
    }
}
